import * as THREE from 'three';
import {environmentState} from './league.js';
export class VoyageWorld{
 constructor(context,level){this.c=context;this.level=level;this.root=context.world;this.theme=level.theme;this.lastPhase=-1;this.spinners=[];this.kelp=[];this.portalRings=[];this.ventRings=[];this.shaderUniforms=[];if(!this.theme){this.fieldDevices();return;}if(this.theme==='seabed')this.seabed();else this.space();this.fieldDevices();}
 mesh(geometry,color,parent=this.root,options={}){const mesh=new THREE.Mesh(geometry,this.c.material(color,options));parent.add(mesh);return mesh;}
 planet(position,radius,color,ringed=false){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=256;const ctx=canvas.getContext('2d'),base=new THREE.Color(color);for(let y=0;y<256;y++){const strength=.6+Math.sin(y*.13)*.12+Math.sin(y*.37)*.06;const rgb=base.clone().multiplyScalar(strength);ctx.fillStyle='#'+rgb.getHexString();ctx.fillRect(0,y,512,1);}const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const planet=this.mesh(new THREE.SphereGeometry(radius,40,28),color,this.root,{map:texture,roughness:.9,metalness:0});planet.position.set(...position);planet.rotation.z=.25;this.spinners.push({mesh:planet,axis:'y',speed:.025});const atmosphere=new THREE.Mesh(new THREE.SphereGeometry(radius*1.06,32,20),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.13,side:THREE.BackSide,depthWrite:false,blending:THREE.AdditiveBlending}));planet.add(atmosphere);if(ringed){const rings=new THREE.Group();rings.rotation.x=.85;rings.rotation.z=.2;planet.add(rings);for(let i=0;i<4;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(radius*(1.4+i*.13),.025+i*.012,4,96),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.2+i*.07,toneMapped:false}));rings.add(ring);}}return planet;}
 space(){const {c,root,level}=this;c.scene.fog.density=.005;const starCount=900,positions=new Float32Array(starCount*3),colors=new Float32Array(starCount*3);for(let i=0;i<starCount;i++){const a=i*2.39996,rad=27+(i%19)*.9,y=Math.sin(i*7.31)*19;positions.set([Math.cos(a)*rad,y,Math.sin(a)*rad],i*3);const color=new THREE.Color(i%7===0?0xffc38c:i%5===0?0xc7aaff:0xc2e9ff);colors.set([color.r,color.g,color.b],i*3);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));this.stars=new THREE.Points(geometry,new THREE.PointsMaterial({size:.08,vertexColors:true,transparent:true,opacity:.9,sizeAttenuation:true,depthWrite:false}));root.add(this.stars);
  for(const [x,y,z,color,size] of [[0,7,-23,0x522674,27],[-16,5,-13,0x194b7b,20],[14,2,-18,0x653550,20]]){const cloud=c.glow(root,color,size,.12);cloud.position.set(x,y,z);}
  if(this.theme==='station'){this.planet([-12,3,-10],3.1,0xb0a2d5);this.planet([10,5,-17],4.6,0x675dba,true);this.gyro=new THREE.Group();this.gyro.position.set(0,2,-8);root.add(this.gyro);for(let i=0;i<3;i++){const mesh=new THREE.Mesh(new THREE.TorusGeometry(5.8+i*.23,.045,6,100),new THREE.MeshBasicMaterial({color:i===1?0xbca4ff:0x4f6b9e,transparent:true,opacity:i===1?.65:.35,toneMapped:false}));mesh.rotation.x=i*.24;mesh.rotation.y=i*.3;this.gyro.add(mesh);}for(let i=0;i<4;i++){const angle=i*Math.PI/2;c.box(this.gyro,Math.cos(angle)*5.8,Math.sin(angle)*5.8,0,.4,.4,.18,0x8b79ba);}const station=new THREE.Group();station.position.set(-10,-.1,4);root.add(station);c.box(station,0,0,0,1.8,1.1,1.2,0x6c779b);for(let side of [-1,1]){c.box(station,side*2.2,0,0,2.5,.08,1.8,0x284d6c);for(let x=0;x<5;x++)c.box(station,side*(1.1+x*.45),.055,0,.018,.02,1.7,0x72acd1,true);}this.spinners.push({mesh:station,axis:'z',speed:.05});}
  else if(this.theme==='space'){this.planet([11,4,-14],5.1,0xd7975b,true);this.planet([-13,5,-16],2.3,0x5b8ab3);const ship=new THREE.Group();ship.position.set(-8,.5,-7);ship.rotation.y=-.5;root.add(ship);const fuselage=this.mesh(new THREE.ConeGeometry(.7,3.4,5),0xa3b6c6,ship,{metalness:.65,roughness:.3});fuselage.rotation.z=-Math.PI/2;c.box(ship,-.5,-.1,0,1.2,.12,3.5,0x627895);const exhaust=c.glow(ship,0x7abfff,3.1,.3);exhaust.position.x=-1.8;this.spinners.push({mesh:ship,axis:'z',speed:.015});const linePositions=[];for(let i=0;i<100;i++){const x=Math.sin(i*29.1)*22,y=2+Math.sin(i*8.3)*7,z=Math.cos(i*9.2)*24;linePositions.push(x,y,z,x+.3+(i%5)*.12,y,z);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(linePositions,3));this.windLines=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color:0xabcaff,transparent:true,opacity:.25}));root.add(this.windLines);}
  else {this.planet([-13,4,-16],2.8,0x9e6bc8);const gate=new THREE.Group();gate.position.set(0,5,-14);gate.rotation.x=.15;root.add(gate);this.rift=gate;for(let i=0;i<4;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(4.7+i*.18,.03+i*.015,6,100),new THREE.MeshBasicMaterial({color:i%2?0xf4aaff:0x73ede7,transparent:true,opacity:.5-i*.08,toneMapped:false}));gate.add(ring);ring.rotation.x=i*.14;this.spinners.push({mesh:ring,axis:'z',speed:(i%2?1:-1)*.03});}const uniforms={time:{value:0},energy:{value:1}};const material=new THREE.ShaderMaterial({uniforms,transparent:true,side:THREE.DoubleSide,depthWrite:false,vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec2 vUv;uniform float time;uniform float energy;void main(){vec2 p=(vUv-.5)*2.;float r=length(p);float a=atan(p.y,p.x);float spiral=.5+.5*sin(a*3.+r*30.-time*.8);float band=exp(-pow((r-.65)*5.,2.));vec3 color=mix(vec3(.22,.11,.5),vec3(.6,.95,1.),spiral);float alpha=band*(.25+spiral*.5)*(.45+energy*.55);gl_FragColor=vec4(color,alpha);}'});const disc=new THREE.Mesh(new THREE.CircleGeometry(4.7,96),material);gate.add(disc);this.shaderUniforms.push(uniforms);const black=this.mesh(new THREE.SphereGeometry(1.8,32,24),0x02020b,gate,{roughness:1,metalness:0});black.position.z=-.2;for(let i=0;i<20;i++){const rock=this.mesh(new THREE.IcosahedronGeometry(.2+(i%4)*.12,0),i%2?0x5c5478:0x6f6876);rock.position.set(Math.cos(i*2.39)*12,-.7+Math.sin(i*3.1)*1.6,Math.sin(i*2.39)*10);rock.rotation.set(i*.3,i*.7,0);this.spinners.push({mesh:rock,axis:'y',speed:.03+(i%3)*.025});}}
 }
 seabed(){const {c,root}=this;c.scene.fog.density=.035;c.scene.fog.color.set(0x092c39);const terrain=new THREE.PlaneGeometry(38,32,32,24),attribute=terrain.attributes.position;for(let i=0;i<attribute.count;i++){const x=attribute.getX(i),y=attribute.getY(i);attribute.setZ(i,Math.sin(x*.48)*Math.cos(y*.31)*.28+Math.sin(x*.8+y*.3)*.12);}terrain.computeVertexNormals();const sand=this.mesh(terrain,0x537168,root,{roughness:1,metalness:0});sand.rotation.x=-Math.PI/2;sand.position.y=-.62;sand.receiveShadow=true;
  for(let i=0;i<26;i++){const x=i<13?-7-(i%4)*.7:7+(i%4)*.7,z=-8+(i%13)*1.25,stalk=new THREE.Group();stalk.position.set(x,-.6,z);root.add(stalk);for(let leaf=0;leaf<4;leaf++){const mesh=this.mesh(new THREE.SphereGeometry(.35,8,6),i%3===0?0x4eaca1:0x285f63,stalk,{roughness:.8});mesh.scale.set(.3,1.5+leaf*.25,.7);mesh.position.set(Math.sin(leaf*1.4)*.3,.8+leaf*.65,0);mesh.rotation.z=Math.sin(leaf*2.1)*.35;}this.kelp.push(stalk);}
  for(let i=0;i<14;i++){const coral=new THREE.Group();coral.position.set(Math.cos(i*2.399)*(7+i%3),-.6,Math.sin(i*2.399)*(6+i%2));root.add(coral);for(let branch=0;branch<5;branch++){const mesh=this.mesh(new THREE.CylinderGeometry(.04,.1,.7+branch*.2,5),i%2?0xb36fa8:0x5ea79b,coral,{roughness:.55});mesh.position.set(Math.sin(branch*2.4)*.27,.4+branch*.1,Math.cos(branch*2.4)*.27);mesh.rotation.z=Math.sin(branch*2.3)*.5;}}
  const wreck=new THREE.Group();wreck.position.set(-10,-.35,1);wreck.rotation.z=.17;wreck.rotation.y=.45;root.add(wreck);c.box(wreck,0,0,0,2.1,.5,4.3,0x324f50);for(let i=0;i<5;i++){const arch=new THREE.Mesh(new THREE.TorusGeometry(1.1,.06,5,20,Math.PI),c.material(0x587273));arch.position.z=-1.7+i*.8;arch.rotation.x=Math.PI/2;wreck.add(arch);}c.box(wreck,0,1.2,0,.08,2.8,.08,0x52746e);c.box(wreck,0,2.3,0,1.9,.06,.08,0x52746e);
  for(let i=0;i<5;i++){const beam=new THREE.Mesh(new THREE.ConeGeometry(1.1+i*.15,12,16,1,true),new THREE.MeshBasicMaterial({color:0x8adbe1,transparent:true,opacity:.025,side:THREE.DoubleSide,depthWrite:false,blending:THREE.AdditiveBlending}));beam.position.set(-9+i*4,5,-6);beam.rotation.z=-.15;root.add(beam);}
  this.fish=new THREE.InstancedMesh(new THREE.ConeGeometry(.055,.25,5),c.material(0x80b9b3,{roughness:.6}),35);root.add(this.fish);this.fish.frustumCulled=false;this.fishDummy=new THREE.Object3D();
  const uniforms={time:{value:0},energy:{value:1}};const caustic=new THREE.Mesh(new THREE.PlaneGeometry(36,30),new THREE.ShaderMaterial({uniforms,transparent:true,depthWrite:false,side:THREE.DoubleSide,vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec2 vUv;uniform float time;void main(){vec2 p=vUv*35.;float a=sin(p.x+sin(p.y+time*.2))*cos(p.y*.8+sin(p.x-time*.15));float glow=pow(max(0.,a),10.);gl_FragColor=vec4(.5,.9,.9,glow*.11);}'}));caustic.rotation.x=-Math.PI/2;caustic.position.y=-.2;root.add(caustic);this.shaderUniforms.push(uniforms);
 }
 fieldDevices(){const {c,level}=this,root=c.course;this.forceArrows=new THREE.Group();this.forceArrows.position.set(-level.width/2-.9,.15,0);root.add(this.forceArrows);if(['gravity','wind','tide'].includes(level.mechanic)||level.captainRule==='surge'){for(let i=0;i<3;i++){const arrow=this.mesh(new THREE.ConeGeometry(.1,.35,4),level.color,this.forceArrows,{emissive:level.color,emissiveIntensity:.5});arrow.rotation.z=-Math.PI/2;arrow.position.set(.2+i*.3,0,0);}}
  for(const portal of level.portals||[]){for(const [i,point] of [portal.from,portal.to].entries()){const p=c.point(...point),ring=c.ring(root,p.x,.09,p.z,.4,i===0?0xeaa1ff:0x75f7d4);const inner=c.ring(root,p.x,.11,p.z,.25,i===0?0xc47cff:0x96ffe5);this.portalRings.push(ring,inner);const glow=c.glow(root,i===0?0xeaa1ff:0x75f7d4,1.5,.28);glow.position.set(p.x,.25,p.z);}}
  for(const [x,y] of level.pulsingHazards||[]){const p=c.point(x,y);const chimney=this.mesh(new THREE.CylinderGeometry(.16,.38,.65,7),0x36515b);chimney.position.set(p.x,.29,p.z);const ring=c.ring(root,p.x,.67,p.z,.23,0xff92c7);this.ventRings.push(ring);}
  if(level.orbitingHazard){this.meteor=this.mesh(new THREE.IcosahedronGeometry(.35,0),0x967797,root,{emissive:0x713365,emissiveIntensity:.4});this.meteor.position.y=.45;}
 }
 setPhase(phase){if(!this.theme&&this.level.captainRule!=='surge')return;const env=environmentState(this.level,phase);if(phase===this.lastPhase)return;this.lastPhase=phase;this.env=env;const angle=({'→':0,'↓':Math.PI/2,'←':Math.PI,'↑':-Math.PI/2}[env.arrow]||0);if(this.gyro)this.c.gsap.to(this.gyro.rotation,{z:Math.floor(phase/2)*Math.PI/2,duration:.4,ease:'power2.inOut'});if(this.forceArrows)this.c.gsap.to(this.forceArrows.rotation,{y:-angle,duration:.3});for(const ring of this.portalRings){ring.material.transparent=true;ring.material.opacity=env.portal?1:.2;}for(const ring of this.ventRings){ring.material.color.set(env.energy?0xff85c8:0x366c72);ring.material.opacity=env.energy?1:.3;ring.material.transparent=true;}for(const uniforms of this.shaderUniforms)if(uniforms.energy)uniforms.energy.value=env.energy?1:0;
  if(this.meteor){const p=this.c.point(this.level.orbitingHazard.x,this.level.orbitingHazard.rows[phase]);this.c.gsap.to(this.meteor.position,{x:p.x,y:.45,z:p.z,duration:.18});}if(this.windLines)this.windLines.rotation.y=phase<4?0:Math.PI;}
 update(time){if(!this.theme)return;for(const {mesh,axis,speed} of this.spinners)mesh.rotation[axis]+=speed/30;for(let i=0;i<this.kelp.length;i++)this.kelp[i].rotation.z=Math.sin(time*.7+i)*.09;if(this.stars)this.stars.rotation.y=time*.002;for(const uniform of this.shaderUniforms)uniform.time.value=time;
  if(this.fish){const d=this.fishDummy;for(let i=0;i<35;i++){d.position.set(Math.sin(time*.12+i*.31)*8,1.5+Math.sin(i*2.1+time*.4)*.4,-5.5+Math.cos(i*.8)*1.5);d.rotation.z=-Math.PI/2;d.rotation.y=Math.cos(time*.12+i*.31)>0?0:Math.PI;d.updateMatrix();this.fish.setMatrixAt(i,d.matrix);}this.fish.instanceMatrix.needsUpdate=true;}
  for(let i=0;i<this.portalRings.length;i++)this.portalRings[i].scale.setScalar(1+Math.sin(time*2+i)*.06);
 }
}
